// Look up cum_k(theta) conservatively: returns a lower bound such that
// `eps < lookup_cum(eps, theta, k)` ⇒ no Clifford+kD circuit within eps exists at theta.
// Theta should be in [0, 2π); values outside are wrapped via fmod.
inline double lookup_cum(double theta, int k) {
    if (k < 0) return 0.0;
    if (k > 2) k = 2;  // table only goes to k=2
    double t = theta;
    while (t < 0)             t += THETA_PERIOD;
    while (t >= THETA_PERIOD) t -= THETA_PERIOD;
    // Find adjacent grid points by linear scan (N=99, fast enough); could binary-search.
    int lo = 0, hi = N_GRID - 1;
    for (int i = 0; i < N_GRID; ++i) {
        if (THETA_GRID[i] <= t) lo = i;
        if (THETA_GRID[i] >= t) { hi = i; break; }
    }
    const double* arr = (k == 0) ? CUM_0 : (k == 1) ? CUM_1 : CUM_2;
    double v = (arr[lo] < arr[hi]) ? arr[lo] : arr[hi];
    v -= SAFETY_MARGIN;
    return (v > 0.0) ? v : 0.0;
}


inline bool is_clifford_z_angle(double theta) {
    constexpr double period_clifford = 4.18879020478639098461685;  // 4π/3
    double r = theta;
    while (r < 0)              r += period_clifford;
    while (r >= period_clifford) r -= period_clifford;
    constexpr double tol = 1e-9;
    return r < tol || (period_clifford - r) < tol;
}


// Returns true if Clifford+kD search at any depth k ∈ [0, max_d] is provably unable
// to find a circuit within eps of R^Z(theta).  Always false at Clifford-Z angles.
//
// Empirical finding (2026-05-08, confirmed at 24 angles via calibrate_direct.py):
// For the qutrit Clifford+D group, cum_K(θ) saturates at K=2.  best_3, best_4, ...
// equal best_2 to floating-point precision (~1e-15 difference) at every angle tested,
// because depth-3+ word sets do not add geometrically closer matrices to R^Z(θ).
// Therefore we use cum_2 as the lower bound for any max_d ≥ 2.
inline bool should_skip_direct(double eps, double theta, int max_d) {
    if (is_clifford_z_angle(theta)) return false;
    int k = (max_d > 2) ? 2 : max_d;  // cum saturates at K=2; clamp lookup
    return eps < lookup_cum(theta, k);
}
